//! Cusps of Gamma0(N) and the boundary map on weight-2 modular symbols.
//!
//! Cusp classes use Cremona's criterion: in lowest terms, u1/v1 ~ u2/v2
//! under Gamma0(N) iff s1 v2 = s2 v1 (mod gcd(v1 v2, N)), where
//! u_j s_j = 1 (mod v_j).  The cusp oo is replaced by 1/N (they are
//! equivalent: [1 0; N 1] oo = 1/N).  For the sign +1 quotient, x and -x
//! are identified as well.
//!
//! The Manin symbol (c : d), lifted to g = [a b; c d] in SL_2(Z), is the
//! modular symbol g{0, oo} = {b/d, a/c}, with boundary [a/c] - [b/d].

use crate::p1::{gcd, xgcd};
use crate::presentation::Presentation;

pub struct Cusps {
    n: i64,
    sign_plus: bool,
    /// Class representatives (u, v) in lowest terms, v > 0.
    reps: Vec<(i64, i64)>,
}

fn normalize(u: i64, v: i64, n: i64) -> (i64, i64) {
    if v == 0 {
        return (1, n); // oo ~ 1/N
    }
    let g = gcd(u.unsigned_abs(), v.unsigned_abs()) as i64;
    let (u, v) = (u / g, v / g);
    if v < 0 { (-u, -v) } else { (u, v) }
}

fn inverse_mod(u: i64, v: i64) -> i64 {
    if v == 1 {
        return 0;
    }
    let (_, s) = xgcd(u.rem_euclid(v), v);
    s.rem_euclid(v)
}

impl Cusps {
    pub fn new(n: u64, sign_plus: bool) -> Self {
        Cusps { n: n as i64, sign_plus, reps: vec![] }
    }

    fn equivalent(&self, (u1, v1): (i64, i64), (u2, v2): (i64, i64)) -> bool {
        let n = self.n as i128;
        let (v1, v2) = (v1 as i128, v2 as i128);
        let m = gcd((v1 * v2 % n) as u64, n as u64) as i128;
        let m = if m == 0 { n } else { m };
        let (s1, s2) = (inverse_mod(u1, v1 as i64) as i128, inverse_mod(u2, v2 as i64) as i128);
        (s1 * v2 - s2 * v1).rem_euclid(m) == 0
    }

    /// The index of the class of u/v (added if new).
    pub fn class(&mut self, u: i64, v: i64) -> usize {
        let c = normalize(u, v, self.n);
        let neg = normalize(-c.0, c.1, self.n);
        if let Some(i) = self.reps.iter().position(|&r| self.equivalent(r, c) || (self.sign_plus && self.equivalent(r, neg))) {
            return i;
        }
        self.reps.push(c);

//! The values of a modular symbol functional on closed cycles.
//!
//! Each Manin symbol (c : d), lifted to g = [a b; c d] in SL_2(Z), is the
//! path g{0, oo} = {b/d, a/c}: an edge of a graph whose vertices are the
//! cusp classes of Gamma0(N) (cusps.rs).  Integer combinations of edges
//! with zero boundary are the cycles of this graph, and they map onto
//! H_1(X_0(N), Z) (Manin, Parabolic points and zeta functions of modular
//! curves, 1972, Thm 1.9).  The fundamental cycles of a spanning forest
//! are a Z-basis of the cycles, so the gcd of X over them generates
//! X(H_1(X_0(N), Z)).
//!
//! For a cusp r Gamma0(N)-equivalent to 0 the path {0, r} is closed, so
//! X({0, r}) lies in this lattice: this bounds the denominators of the
//! modular symbols [a/p^k] (p not dividing N) used by p-adic L-series.

use crate::cusps::{lift_to_sl2, Cusps};
use crate::p1::P1List;
use num_traits::{Signed, Zero};
use sagebrush_bigint::BigInt;

fn gcd_big(a: &BigInt, b: &BigInt) -> BigInt {
    let (mut a, mut b) = (a.abs(), b.abs());
    while !b.is_zero() {
        let r = &a % &b;
        a = std::mem::replace(&mut b, r);
    }
    a
}

/// A union-find over cusp classes that keeps, for each class, the value
/// of X along a forest path from its root: pot(v) = X({root, v}).
struct Forest {
    parent: Vec<usize>,
    /// X({parent, v})
    up: Vec<BigInt>,
}

impl Forest {
    fn add(&mut self) {
        self.parent.push(self.parent.len());
        self.up.push(BigInt::zero());
    }

    /// (root, X({root, v}))
    fn find(&mut self, v: usize) -> (usize, BigInt) {
        let mut path = vec![];
        let mut r = v;
        while self.parent[r] != r {
            path.push(r);
            r = self.parent[r];
        }
        // compress: from the node nearest the root outwards
        let mut acc = BigInt::zero();
        for &u in path.iter().rev() {
            acc = &acc + &self.up[u];
            self.up[u] = acc.clone();
            self.parent[u] = r;
        }
        (r, if v == r { BigInt::zero() } else { self.up[v].clone() })
    }

//! Dimension formulas, independent of any modular symbols presentation:
//! S_k(N, eps) by Cohen-Oesterle, E_k(N, eps) by counting eps-regular cusps,
//! and the modular symbols space M_k(Gamma0(N), eps) (sign 0) via
//! Eichler-Shimura, dim = 2 dim S_k + dim E_k (k >= 2).
//!
//! These certify the dimensions found mod ell (which can only be too
//! large): equality proves that ell is good for the presentation.  For sign
//! +1 or -1 no split formula is needed: M = M^+ (+) M^-, so
//! dim_ell M^+ + dim_ell M^- = dim M certifies both.

use crate::exact::{factor, level_data};
use crate::general::Character;

fn parity_ok(eps: &Character, k: usize) -> bool {
    eps.is_even() == (k % 2 == 0)
}

/// Cohen-Oesterle's lambda(r_p, s_p, p).
fn lambda(r: u32, s: u32, p: u64) -> u64 {
    if 2 * s <= r {
        if r % 2 == 0 {
            p.pow(r / 2) + p.pow(r / 2 - 1)
        } else {
            2 * p.pow((r - 1) / 2)
        }
    } else {
        2 * p.pow(r - s)
    }
}

/// sum of eps(x) over x mod N with f(x) = 0 mod N, as a complex number.
fn character_sum(eps: &Character, f: impl Fn(u64) -> u64) -> (f64, f64) {
    let n = eps.n;
    let mut s = (0.0, 0.0);
    for x in 0..n {
        if f(x) % n == 0 {
            let e = eps.exponent(x as i64).expect("a root of x^2+1 or x^2+x+1 is a unit");
            let t = 2.0 * std::f64::consts::PI * e as f64 / eps.order as f64;
            s.0 += t.cos();
            s.1 += t.sin();
        }
    }
    s
}

/// dim S_k(Gamma0(N), eps) for k >= 2 (Cohen-Oesterle).
pub fn dim_cusp_forms(eps: &Character, k: usize) -> u64 {
    assert!(k >= 2);
    if !parity_ok(eps, k) {
        return 0;
    }
    let n = eps.n;
    let f = eps.conductor();
    let psi = level_data(n).0 as f64;
    let lam: u64 = factor(n).iter().map(|&(p, r)| {
        let s = factor(f).iter().find(|&&(q, _)| q == p).map_or(0, |&(_, s)| s);
        lambda(r, s, p)
    }).product();
    let g4 = match k % 4 { 2 => -0.25, 0 => 0.25, _ => 0.0 };
    let g3 = match k % 3 { 2 => -1.0 / 3.0, 0 => 1.0 / 3.0, _ => 0.0 };

//! The group of Dirichlet characters mod N: generators of (Z/N)^*,
//! discrete logarithms, every character as an exponent table, conductors,
//! and characters from LMFDB's description (values on generators).

use crate::exact::factor;
use crate::general::Character;
use crate::p1::gcd;

/// (Z/N)^* as a product of cyclic groups <g_i> of orders o_i, with the
/// discrete logarithm of every unit.  Characters are vectors c with
/// chi(g_i) = zeta_(o_i)^(c_i); `exponent` is lcm(o_i), the exponent of the
/// group, and values are reported relative to zeta_exponent.
#[derive(Clone, Debug)]
pub struct DirichletGroup {
    pub n: u64,
    pub gens: Vec<u64>,
    pub orders: Vec<u64>,
    pub exponent: u64,
    /// logs[x]: exponent vector of x in the generators (empty for non-units).
    logs: Vec<Vec<u64>>,
    /// For each generator: the prime power p^r of N it lives in, and for
    /// p = 2 whether it is 5 (order 2^(r-2)) rather than -1 (order 2).
    parts: Vec<(u64, u32, bool)>,
}

fn crt_lift(a: u64, q: u64, n: u64) -> u64 {
    // The x mod n with x = a mod q and x = 1 mod n/q (q | n, gcd(q, n/q) = 1).
    let r = n / q;
    (0..q).map(|t| 1 + t * r).find(|x| x % q == a % q).unwrap() % n.max(1)
}

impl DirichletGroup {
    pub fn new(n: u64) -> Self {
        let mut gens = vec![];
        let mut orders = vec![];
        let mut parts = vec![];
        for (p, r) in factor(n) {
            let q = p.pow(r);
            if p == 2 {
                if r >= 2 {
                    gens.push(crt_lift(q - 1, q, n));
                    orders.push(2);
                    parts.push((2, r, false));
                }
                if r >= 3 {
                    gens.push(crt_lift(5, q, n));
                    orders.push(q / 4);
                    parts.push((2, r, true));
                }
            } else {
                // The least primitive root mod p^r.
                let phi = q / p * (p - 1);
                let fs: Vec<u64> = factor(phi).iter().map(|&(f, _)| f).collect();
                let g = (2..q).find(|&g| gcd(g, p) == 1 && fs.iter().all(|&f| pow_mod(g, phi / f, q) != 1)).unwrap();
                gens.push(crt_lift(g, q, n));
                orders.push(phi);
                parts.push((p, r, false));
            }
        }
        let exponent = orders.iter().fold(1u64, |l, &o| l / gcd(l, o) * o);

//! The modular symbol map of an elliptic curve over Q, sign +1: the
//! functional X on the Manin symbols (c:d) of P^1(Z/NZ) that belongs to the
//! curve's newform (T_q X = a_q X for q not dividing N), as a primitive
//! integer vector, and its values at cusps by Manin's continued fractions.
//!
//! X is computed modulo several 31-bit primes p: the kernel of the stacked
//! T_q - a_q on the quotient of the Manin symbols by the 2- and 3-term
//! relations (presentation.rs, space.rs), for primes q not dividing N until
//! it is one-dimensional, extended to every symbol.  The kernel over Q has
//! dimension at most that over GF(p), so a one-dimensional kernel mod p
//! makes X unique up to a scalar.  The values are lifted by CRT and
//! rational reconstruction, scaled to a primitive integer vector, and then
//! checked exactly: every 3-term relation and T_q X = a_q X for every q
//! used.
//!
//! Evaluation follows psage's modular_symbol_map.pyx (William Stein, ported
//! with his permission: NOTICE.md): with q_0 = 1, q_1, ..., q_n the
//! denominators of the continued fraction convergents of a/b, the sum of
//! X(((-1)^(i-1) q_i : q_(i-1))) for i = 1..n is the symbol {0, a/b} in X's
//! units; the scale and the value at 0 are the caller's (lib/_sage_modular.py
//! normalizes by L-values).

use crate::p1::P1List;
use crate::presentation::Presentation;
use crate::space::Space;
use num_traits::{One, Signed, ToPrimitive, Zero};
use sagebrush_bigint::BigInt;

pub struct EcMap {
    pub n: u64,
    pub p1: P1List,
    /// X on each Manin symbol, by P1List index (primitive, integral)
    pub x: Vec<BigInt>,
    /// the primes q whose Hecke relations were checked
    pub hecke_primes: Vec<u64>,
    /// X on the closed cycles: X(H_1(X_0(N), Z)) = cycles * Z (cycles.rs)
    pub cycles: BigInt,
}

fn kernel_mod(rows: &[Vec<u64>], d: usize, p: u64) -> Vec<Vec<u64>> {
    let (r, piv) = crate::linalg::rref_mod(rows.to_vec(), p);
    let is_piv: Vec<bool> = (0..d).map(|c| piv.contains(&c)).collect();
    (0..d).filter(|&c| !is_piv[c]).map(|f| {
        let mut v = vec![0u64; d];
        v[f] = 1;
        for (i, &pc) in piv.iter().enumerate() {
            v[pc] = (p - r[i][f] % p) % p;
        }
        v
    }).collect()
}

