//! Predicted dimension, memory and time before running anything, so a
//! caller (or an agent) can decide what is affordable.  The constants are
//! fitted to measurements on an 8-core AMD EPYC (see results/engine-exact.md).

use crate::exact::{bound_bits, level_data};
use crate::linalg::heilbronn;

pub struct Estimate {
    pub n: u64,
    pub q: u64,
    pub symbols: u64,
    pub dim: u64,
    pub genus: u64,
    /// Primes the exact characteristic polynomial typically needs (the
    /// proven bound from the sum of squares, with Sato-Tate's r = sqrt(q)),
    /// and at most (the worst-case Deligne bound).
    pub primes: u64,
    pub primes_max: u64,
    /// Peak bytes for one prime, and for the exact computation (up to 8
    /// primes are in flight at once).
    pub bytes_modp: f64,
    pub bytes_exact: f64,
    /// Single-thread seconds for one prime, and for the exact computation.
    pub seconds_modp: f64,
    pub seconds_exact: f64,
}

// Fitted on one thread for dim 84..3334: free generators are psi/4; the
// elimination constant is an upper bound (highly composite levels have the
// most fill-in, prime levels are ~5x cheaper); the charpoly constant grows
// once the matrix leaves the cache.
const GENS_PER_SYMBOL: f64 = 0.25;
const ELIM: f64 = 4e-8;
const HECKE: f64 = 3e-9;
const CHARPOLY: f64 = 4.4e-10;

pub fn estimate(n: u64, q: u64) -> Estimate {
    let (psi, genus, _, eis, dim) = level_data(n);
    let (m, d) = (GENS_PER_SYMBOL * psi as f64, dim as f64);
    let h = heilbronn(q as i64).len() as f64;
    let primes_max = (bound_bits(q, genus, eis) / 30.99).ceil();
    let typical = genus as f64 * (1.0 + (q as f64).sqrt()).log2() + eis as f64 * (2.0 + q as f64).log2() + 2.0;
    let primes = (typical / 30.99).ceil().min(primes_max);
    // Dense coordinates of every free generator dominate, then the matrix.
    let bytes_modp = 8.0 * m * d + 4.0 * d * d + 3e6;
    let seconds_modp = ELIM * m * d + HECKE * h * d * d + CHARPOLY * (1.0 + d / 4000.0) * d * d * d;
    Estimate {
        n,
        q,
        symbols: psi,
        dim,
        genus,
        primes: primes as u64,
        primes_max: primes_max as u64,
        bytes_modp,
        bytes_exact: bytes_modp * primes.min(8.0),
        seconds_modp,
        seconds_exact: seconds_modp * primes,
    }
}

//! Exact characteristic polynomials over Z, with a proof sketch.
//!
//! Let L be the integral plus-quotient of weight-2 modular symbols for
//! Gamma0(N) modulo torsion.  Its rank is g + e, where g is the genus of
//! X0(N) and e + 1 is the number of cusps up to the involution x -> -x
//! (the Eisenstein part of the plus space is the degree-zero part of the
//! cusp divisors fixed by that involution).  T_q acts on L integrally.
//! Over GF(p) the Manin-symbol presentation gives M(Z) (x) GF(p) (right
//! exactness); if its dimension equals g + e the torsion vanishes at p, so
//! the mod-p characteristic polynomial is the reduction of the integral
//! one.  Eigenvalues satisfy |a| <= 2 sqrt(q) on cusp forms (Eichler-Shimura
//! + Weil) and |a| <= 1 + q on Eisenstein series, which bounds the
//! coefficients; CRT over enough good primes then determines the
//! polynomial exactly.

use crate::linalg;
use crate::par;
use crate::presentation::Presentation;
use crate::space::Space;
use sagebrush_bigint::{BigInt, BigUint};
use num_traits::{One, Signed, ToPrimitive, Zero};

pub fn factor(mut n: u64) -> Vec<(u64, u32)> {
    let mut out = vec![];
    let mut p = 2;
    while p * p <= n {
        let mut e = 0;
        while n % p == 0 {
            n /= p;
            e += 1;
        }
        if e > 0 {
            out.push((p, e));
        }
        p += 1;
    }
    if n > 1 {
        out.push((n, 1));
    }
    out
}

fn kronecker_minus(d: i64, p: u64) -> i64 {
    // (d/p) for d in {-1, -3}, p prime
    let p = p as i64;
    if d == -1 {
        return if p == 2 { 0 } else if p % 4 == 1 { 1 } else { -1 };
    }
    if p == 3 {
        0
    } else if p % 3 == 1 {
        1
    } else {
        -1
    }
}

/// Level data for X0(N): (psi(N), genus, cusps, Eisenstein dimension of the
/// sign +1 space, dimension of the sign +1 space).
pub fn level_data(n: u64) -> (u64, u64, u64, u64, u64) {

//! Modular symbols of any weight k >= 2 on Gamma0(N) with a Dirichlet
//! character eps, sign +1, -1 or 0, over a prime field F_ell with
//! ell = 1 mod ord(eps) (so eps takes its values in F_ell).
//!
//! Manin symbols are [P, (c, d)] = g (P {0, oo}) for P = X^i Y^(k-2-i) and
//! g in SL_2(Z) with bottom row (c, d).  A matrix h = [a b; c d] acts on the
//! right by
//!     [P, (u, v)] h = [P(aX + bY, cX + dY), (u, v) h],
//! and every relation and Hecke operator is written with this one action:
//!   * x + x sigma = 0,            sigma = [0 -1; 1 0]
//!   * x + x tau + x tau^2 = 0,    tau = [0 -1; 1 -1]
//!   * x = sign x eta,             eta = [-1 0; 0 1]   (if sign != 0)
//!   * [P, (l c, l d)] = eps(l)^CONV [P, (c, d)] for units l, so a symbol
//!     whose stabilizer meets the character nontrivially is zero;
//!   * T_p x = sum over Merel's matrices (ad - bc = p, a > b >= 0,
//!     d > c >= 0) of x h; for p | N, terms whose bottom row leaves
//!     P^1(Z/N) are dropped, which gives U_p.
//! The 2-term relations (sigma, eta) are solved by a union-find whose
//! edges carry weights in F_ell^*; the 3-term relations become sparse rows
//! on the remaining free generators, eliminated as in weight 2.

use crate::exact::is_prime;
use crate::linalg;
use crate::p1::{gcd, P1List};
use crate::par;

/// Direction of the character relation: -1 means [P, (l c, l d)] =
/// eps(l) [P, (c, d)], Sage's convention (+1 disagrees with Sage on 664 of
/// 1452 test spaces; see examples/general_vs_sage.rs).
const CONV: i64 = -1;

