fn find(parent: &mut [u32], neg: &mut [bool], i: usize) -> (usize, bool) {
    let mut path = vec![];
    let (mut r, mut s) = (i, false);
    while parent[r] as usize != r {
        path.push(r);
        s ^= neg[r];
        r = parent[r] as usize;
    }
    let mut acc = s; // path compression, signs relative to the root
    for &k in &path {
        let next = neg[k];
        parent[k] = r as u32;
        neg[k] = acc;
        acc ^= next;
    }
    (r, s)
}

impl Presentation {
    pub fn new(n: u64) -> Self {
        let p1 = P1List::new(n);
        let ns = p1.len();
        let mut parent: Vec<u32> = (0..ns as u32).collect();
        let mut neg = vec![false; ns];
        let mut zero = vec![false; ns];
        let mut union = |parent: &mut Vec<u32>, neg: &mut Vec<bool>, i: usize, j: usize, minus: bool| {
            let (ri, si) = find(parent, neg, i);
            let (rj, sj) = find(parent, neg, j);
            if ri == rj {
                if si != (sj ^ minus) {
                    zero[ri] = true; // x = -x, so x = 0 (2 is invertible)
                }
                return;
            }
            parent[ri] = rj as u32;
            neg[ri] = si ^ sj ^ minus;
            if zero[ri] {
                zero[rj] = true;
            }

//! The quotient over GF(p): the relations in sparse echelon form, the
//! quotient basis, and Hecke operators.
//!
//! No dense coordinate table is stored.  The relations keep about two
//! nonzeros per row after elimination, so a functional on the quotient
//! extends to every generator in O(m) (`extend`), and the matrix of T_q is
//! assembled a block of columns at a time from such functionals.  Memory is
//! O(m + dim^2) instead of O(m dim).

