        let mut factors = self.level.factors.clone();
        let mut rings: Vec<LocalRing> = self.p1.locals.iter().map(|l| l.ring.clone()).collect();
        let mut splittings = self.splittings.clone();
        if e == 1 {
            factors.remove(k);
            rings.remove(k);
            splittings.remove(k);
