pub fn low_rank(an: &[i64], n: u64, prec: u64) -> Option<LowRank> {
    let (w, value) = l_value(an, n, prec)?;
    value.is_nonzero().then_some(LowRank { w, rank: if w == 1 { 0 } else { 1 }, value })
}

