//! Integral binary quartics with given invariants, for 2-descent on
//! elliptic curves over Q (Birch and Swinnerton-Dyer 1963).
//!
//! g(X, Y) = a X^4 + b X^3 Y + c X^2 Y^2 + d X Y^3 + e Y^4 has invariants
//!   I = 12ae - 3bd + c^2,  J = 72ace + 9bcd - 27ad^2 - 27eb^2 - 2c^3
//! and seminvariants H = 8ac - 3b^2, R = b^3 + 8a^2 d - 4abc, with the syzygy
//!   27 R^2 = 48 a^2 I H - H^3 - 64 a^3 J.
//! Given (a, H) the syzygy fixes R up to sign, and then b (mod 4a, by
//! translations X -> X + kY, which fix a, H and R) fixes c, d and e.
//!
//! Bounds (Stoll and Cremona's covariant, written from the published
//! mathematics): chi(g) = sum_i |g'(alpha_i)|^-1 |X - alpha_i Y|^2 over the
//! roots of g is a positive definite quadratic form covariant under SL2(R).
//! Every SL2(Z) class has a representative with the root z = x + iy of chi(g)
//! in the standard fundamental domain, so y >= sqrt(3)/2.  Writing
//! g = g_t((X - xY)/sqrt y, sqrt y Y) with g_t on the circle of forms whose
//! covariant has root i (the SO(2)-orbit of one of them):
//!   a = a_t / y^2,  H = H_t / y^2,
//! so |a| <= 4/3 max|a_t| and H/a = H_t/a_t over the t with a_t/a >= 3/4.
//! The real orbits with invariants (I, J) that take positive values all
//! contain a form X^4 + c X^2 + d X + e, which gives one point of each circle.
//!
//! The quartics of a 2-descent can be taken of the form P^2 + 4Q
//! (Cremona, Fisher and Stoll 2010, Theorem 1.1, completing the square in
//! their generalised binary quartics y^2 + P y = Q), so b is even.

use std::ops::{Add, Div, Mul, Sub};

#[derive(Clone, Copy, Debug)]
struct C(f64, f64);
impl Add for C {
    type Output = C;
    fn add(self, o: C) -> C {
        C(self.0 + o.0, self.1 + o.1)
    }
}
impl Sub for C {
    type Output = C;
    fn sub(self, o: C) -> C {
        C(self.0 - o.0, self.1 - o.1)
    }
}
impl Mul for C {
    type Output = C;
    fn mul(self, o: C) -> C {
        C(self.0 * o.0 - self.1 * o.1, self.0 * o.1 + self.1 * o.0)
    }
}
impl Div for C {
    type Output = C;
    fn div(self, o: C) -> C {
        let n = o.0 * o.0 + o.1 * o.1;
        C((self.0 * o.0 + self.1 * o.1) / n, (self.1 * o.0 - self.0 * o.1) / n)
    }
}
impl C {
    fn abs(self) -> f64 {
        self.0.hypot(self.1)
    }
}

//! Rational points of small height on an elliptic curve over Q: the x = r/s^2
//! (gcd(r, s) = 1) with |r| <= rmax and s <= smax for which
//!   s^6 (4x^3 + b2 x^2 + 2 b4 x + b6) = 4r^3 + b2 r^2 s^2 + 2 b4 r s^4 + b6 s^6
//! is a square: then (2y + a1 x + a3)^2 = that / s^6 has a rational solution.
//! The caller (lib/_sage_ec.py) lifts each x to the points above it.

use crate::quartic::is_square;

fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        (a, b) = (b, a % b);
    }
    a
}

/// [(r, s)] with x = r/s^2 the x-coordinate of a point (sorted by s, then r),
/// at most `limit` of them; Err if the numbers could leave i128.
pub fn x_coordinates(b2: i128, b4: i128, b6: i128, rmax: u64, smax: u64, limit: usize) -> Result<Vec<(i128, u64)>, String> {
    // every exact evaluation: |F(r, s)| and its Horner partial sums are at
    // most the sum of the absolute terms over |r| <= rmax, s <= smax; s^6
    // itself is formed too, and so are the coefficients b2 s^2, 2 b4 s^4
    // even when rmax = 0 (hence r >= 1 here; 1e37 < 2^127 / 17 leaves room
    // for the rounding of this estimate)
    let (r, s) = (rmax.max(1) as f64, smax as f64);
    if limit == 0 {
        // (at most `limit`: the first point was pushed before the check, the
        // review's ECBALL-F6)
        return Ok(Vec::new());
    }
    let size = 4.0 * r.powi(3) + (b2 as f64).abs() * r * r * s * s + 2.0 * (b4 as f64).abs() * r * s.powi(4) + (b6 as f64).abs() * s.powi(6) + s.powi(6);
    if size > 1e37 {
        return Err("the point search needs numbers beyond 128 bits".into());
    }
