    return a // _gcd(a, b) * b if a and b else 0


def _factor(n):
    f, p = [], 2
    while p * p <= n:
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            f.append((p, e))
        p += 1 if p == 2 else 2
    if n > 1:
        f.append((n, 1))
    return f


def _phi(n):
    r = n
    for p, _ in _factor(n):
        r = r // p * (p - 1)
    return r


