"""One call into the engine: a JSON request, a JSON reply (engine/web)."""

import json as _json
import _sbengine
import _limits


# The engine requests that take an opt-in limit from the session's limits
# (lib/_limits.py; C0's per-area follow-up): the field is sent only when the
# limit is finite and the caller didn't pass it, so requests are unchanged by
# default and explicit arguments win.
_LIMITED = {
    "factor": (("work", "poly.work"),),
    "bnf": (("rounds", "nf.relation_rounds"),),
    "bnf_relations": (("rounds", "nf.relation_rounds"),),
    "quadratic_class_group": (("rounds", "nf.relation_rounds"),),
    "bnf_certify": (("norm_max", "nf.certify_norm_max"), ("index_max", "nf.certify_index_max")),
}


def _with_limits(fn, args):
    fields = _LIMITED.get(fn)
    if fields is None:
        return args
    L = _limits.finalize()
    for field, key in fields:
        v = L[key]
        if field not in args and v != float("inf"):
            args[field] = int(v)
    return args


def call(fn, **args):
    args = _with_limits(fn, args)
    r = _json.loads(_sbengine.call(_json.dumps(dict(fn=fn, **args))))
    if "error" in r:
        if r.get("internal"):
            # a failed proved invariant (an engine bug), never a resource
            # limit or a user error
            raise RuntimeError(r["error"])
        raise ValueError(r["error"])
    return r["ok"]


def call_text(request):
    """The engine's reply text for one JSON request text, unparsed (for a
    caller that builds the request itself and drops each text as soon as
    the next exists: lib/_sage_ffmat.py's echelon transport).  No session
    limit is added: only for fns without a _LIMITED entry."""
    return _sbengine.call(request)


def chi_arg(chi):
    """A character as (order, gens, vals), the engine's form, or None."""
    if chi is None:
        return None
    if hasattr(chi, "_sagebrush_chi"):
        return chi._sagebrush_chi()
    order, gens, vals = chi
    return [int(order), [int(g) for g in gens], [int(v) for v in vals]]

# hmf: Hilbert modular forms over Q(sqrt 5)

Hilbert modular forms of parallel weight 2 over F = Q(sqrt 5), by the
definite method: by Jacquet-Langlands and class number one,
M_2(N) is the space of functions on R^x \ P^1(O_F/N), where R is the
icosian ring (Dembélé 2005, section 3; Dembélé-Voight 2013, section 4).

The structure follows William Stein's PSAGE implementation
(psage/modform/hilbert/sqrt5), ported with his permission
(PROVENANCE.md); departures from it are noted in each module:

* `field`: O_F = Z[w], ideals, primes, factorization;
* `rqf`: any real quadratic field: ideals, primes, the fundamental
  unit, class groups and narrow class groups with representatives,
  principality and totally positive generators (for other fields;
  written from the literature);
* `residue`: O_F/P^e in one Hermite-normal-form representation;
* `p1`: P^1(O_F/N) as a product of local projective lines;
* `quat`: the icosian ring and its 120 units;
* `qresidue`: O_F/P^e over any real quadratic field;
* `quatalg`: over any real quadratic field, a totally definite
  quaternion algebra unramified at every finite place and a certified
  maximal order in it, with local splittings (written from the
  literature);
* `classes`: the right ideal classes of such a maximal order, by
  neighbours and the mass formula, with left orders and unit groups;
* `definite`: M_2(N) over any real quadratic field, by the definite
  method: the basis of orbits, Hecke operators T_P, and the cusp and
  new characteristic polynomials;
* `defnew`: over any real quadratic field, the new subspaces, the
  Galois orbits of newforms and their Hecke eigenvalues;
* `defweight`, `defweightnew`: over any real quadratic field, weights
  (k1, k2) other than (2, 2): the spaces with coefficients, Hecke
  operators modulo degree-one primes, newspaces, newform orbits over F
  and their eigenvalues;
* `gpoly`: polynomials over O_F for any real quadratic field, recovered
  from pairs of conjugate degree-one primes, and factored over F;
* `split`: local splittings R/P^e R = M_2(O_F/P^e), from idempotents;
* `orbits`: the orbits of the units on P^1(O_F/N);
* `theta`: the Hecke elements Theta(p), by lattice enumeration;
* Hecke operators T_p for p not dividing N (`Space::hecke_matrix`);
* `degeneracy`: PSAGE's degeneracy maps from level N to N/p;
* `newspace`: new dimensions and characteristic polynomials, Galois
  orbits of newforms, rational newforms and their a_p;
* `eigen`: the Hecke eigenvalues of every newform, in its coefficient
  field;
* `weight`: weights (k1, k2) other than (2, 2), with coefficients in
  the representation L_k.

Invalid input is an `Err`, never a panic.

*From engine/hmf/src/lib.rs.*
